  async function newProject() { if (!(await safeToReplace())) return; adopt(createProject(), new Map()); setStatus('New project. Add videos and photos to begin.'); }
  async function loadSample() { if (busy || !(await safeToReplace())) return; setBusy('Preparing sample project…'); try { const sample = await createSampleProject(setBusy); adopt(sample.project, sample.blobs); setThumbnails(Object.fromEntries(sample.thumbnails)); setWaveforms(Object.fromEntries(sample.waveforms)); setStatus('Sample loaded: a three-minute adventure with editable photos, clips, music, and narration.'); } catch (cause) { setError(errorMessage(cause)); } finally { setBusy(''); } }
  async function openBlob(blob: Blob, name: string) { let loaded: { project: MovieProject; blobs: Map<string, Blob> }; if (/\.lopemoviebundle$/i.test(name)) loaded = await decodePortable(blob); else { const parsed = parseProject(await blob.text()); loaded = { project: parsed, ...await loadAssets(parsed) }; } adopt(loaded.project, loaded.blobs); setStatus('Project opened. All edit decisions are editable.'); }
