  async function audioOnly(){stopPlayback();setBusy('Mixing audio-only movie…');try{let source=project;const end=Math.max(duration,...project.audio.map(item=>anchoredStart(project,item)+audioDuration(item)));if(!end)throw new Error('Add music, narration, or video sound first.');if(end>duration){const tail=createClip();tail.duration=end-duration;tail.sourceOut=tail.duration;source={...project,clips:[...project.clips,tail]};}const audio=await mixAudio(source,library.current);const channels=audio.numberOfChannels;const data=new ArrayBuffer(44+audio.length*channels*2);const view=new DataView(data);const word=(at:number,text:string)=>[...text].forEach((char,i)=>view.setUint8(at+i,char.charCodeAt(0)));word(0,'RIFF');view.setUint32(4,data.byteLength-8,true);word(8,'WAVE');word(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,channels,true);view.setUint32(24,audio.sampleRate,true);view.setUint32(28,audio.sampleRate*channels*2,true);view.setUint16(32,channels*2,true);view.setUint16(34,16,true);word(36,'data');view.setUint32(40,data.byteLength-44,true);const planes=Array.from({length:channels},(_,channel)=>audio.getChannelData(channel));for(let frame=0;frame<audio.length;frame++)for(let channel=0;channel<channels;channel++){const value=Math.max(-1,Math.min(1,planes[channel][frame]));view.setInt16(44+(frame*channels+channel)*2,Math.round(value*(value<0?32768:32767)),true);}download(new Blob([data],{type:'audio/wav'}),safeName(project.name)+'.wav');setStatus('Audio-only movie downloaded as stereo WAV.');}catch(cause){setError(errorMessage(cause));}finally{setBusy('');}}
