  const tabs = ['Home', 'Animations', 'Visual Effects', 'Project', 'View', ...(clip ? ['Video Tools'] : []), ...(selectedAudio ? [selectedAudio.kind === 'music' ? 'Music Tools' : 'Narration Tools'] : []), ...(textStyle ? ['Text Tools'] : [])];
